#include <linux/personality.h>
#include <linux/version.h>
#include <asm/uaccess.h>

int compat_get_uname(char __user *release, size_t len) {
    int ret = 0;
    char version_str[32];
    int major = LINUX_VERSION_MAJOR;
    int minor = LINUX_VERSION_MINOR;
    int patchlevel = LINUX_VERSION_PATCHLEVEL;

    if (current->personality & UNAME26) {
        snprintf(version_str, sizeof(version_str), "Linux 2.6.%d", (major * 1000) + (minor * 100) + patchlevel);
        ret = strlen(version_str);
        if (len < ret)
            ret = -EINVAL;
        else
            if (copy_to_user(release, version_str, ret))
                ret = -EFAULT;
    } else {
        ret = -EINVAL;
    }

    return ret;
}

#include <linux/personality.h>
#include <linux/unistd.h>
#include <linux/version.h>
#include <asm/uaccess.h>
#include <linux/kernel.h>

int modify_uname_version(char __user *release, size_t len) {
    int version = 2 * (KERNEL_VERSION(3, 0, 0).major - 2) + 6;
    char buffer[32];
    int size;
    unsigned long personality = personality(current->personality);

    if (personality & UNAME26) {
        size = snprintf(buffer, sizeof(buffer), "Linux 2.6.%d", version);
        if (size >= (int)len)
            return -EINVAL;
        if (copy_to_user(release, buffer, size))
            return -EFAULT;
        return size;
    }

    return -EPERM;
}

int compat_get_old_linux_version(char __user *release, size_t len) {
    // Check if the current process's personality indicates 26-character uname mode
    if (current->personality & UNAME26) {
        static char version_string[256];
        int version_code = LINUX_VERSION_CODE;
        int major = 2;
        int minor = 6;
        int patch = (version_code >> 16) & 0xFF;

        // Construct the version string in "Linux 2.6.x" format
        snprintf(version_string, sizeof(version_string), "Linux 2.6.%d", patch);

        // Copy the constructed string to the user buffer
        return strncpy_from_user(release, version_string, len) ?: 0;
    }

    // If not in 26-character mode, return an error
    return -EINVAL;
}

#include <linux/personality.h>
#include <linux/version.h>
#include <string.h>
#include <limits.h>

int modify_uname_version(char __user *release, size_t len) {
    char version_string[32];
    unsigned int version = LINUX_VERSION_CODE;
    int ret;

    if (personality(current->personality) & UNAME26) {
        snprintf(version_string, sizeof(version_string), "Linux 2.6.%u", version % 1000);
    } else {
        snprintf(version_string, sizeof(version_string), "Linux %u.%u.%u", 
                 LINUX_VERSION_MAJOR, LINUX_VERSION_MINOR, LINUX_VERSION_PATCHLEVEL);
    }

    ret = strlen(version_string) + 1;
    if (len < (size_t)ret) {
        ret = -EFAULT;
    } else {
        if (copy_to_user(release, version_string, ret)) {
            ret = -EFAULT;
        }
    }

    return ret;
}
